MOTO = re.compile(r"^(\d{3}[A-Z]{3}|[A-Z]\d{3}[A-Z]{3})$")


def completar_origen(apps, schema_editor):
    """Vehículos cargados antes del plan B: se les asigna un origen coherente."""
    Vehiculo = apps.get_model("vehiculos", "Vehiculo")
    for v in Vehiculo.objects.all():
        if MOTO.match(v.patente):
            v.categoria, v.categoria_origen, v.estado_validacion = "MOTO", "FORMATO", "VALIDADO"
        elif v.categoria:
            v.categoria_origen = "DATACAR"
        else:
            v.estado_validacion = "PENDIENTE"  # incluye los RECHAZADO: ahora pueden declarar
        v.save(update_fields=["categoria", "categoria_origen", "estado_validacion"])



